class BruteCLI:
    def __init__(self, job: dict):
        self.job   = job
        self.q     = queue.Queue()
        self.found = False
        self.lock  = threading.Lock()

    # build combo queue --------------------------------------------------------
    def prepare(self):
        users = self._read(self.job.get("userlist"), COMMON_USERS)
        if self.job.get("username"):
            users = [self.job["username"]]
        pwds  = self._read(self.job.get("passlist"), COMMON_PASSWORDS)
        for u in users:
            for p in pwds:
                self.q.put((u, p))

    @staticmethod
    def _read(path, builtin):
        if not path:
            return builtin
        try:
            with open(path, errors="ignore") as f:
                return [ln.strip() for ln in f if ln.strip()]
        except (OSError, IOError):
            print(colored(f"[!] Can't read {path} – using built-in list", "yellow"))
            return builtin

    # one worker thread --------------------------------------------------------
    def worker(self):
        while not self.q.empty() and not self.found:
            u, p = self.q.get()
            if self._try(u, p):
                with self.lock:
                    self.found = True
                    print(colored(f"[+] {u}:{p}", "green", attrs=["bold"]))
            self.q.task_done()

    def _try(self, u, p):
        proto = self.job["protocol"]
        if proto == "ssh":
            return ssh_try(self.job["target"], u, p, port=self.job["port"],
                           timeout=self.job["timeout"])
        if proto == "ftp":
            return ftp_try(self.job["target"], u, p, port=self.job["port"],
                           timeout=self.job["timeout"])
        if proto == "http":
            return http_try(self.job["url"], self.job["user_field"],
                            self.job["pass_field"

import threading
import multiprocessing
from solders.keypair import Keypair

keys_start = ['111', '222', '333', '444', '555', '666', '777', '888', '999', '000',]
keys_end =   ['111', '222', '333', '444', '555', '666', '777', '888', '999', '000']
multiplicator = 0.5

def generate_acc():
    while True:
        account = Keypair()
        address = account.pubkey()

        low_addr = str(address)
        for i in range(len(keys_start)):
            if low_addr.startswith(keys_start[i]) and low_addr.endswith(keys_end[i]):
                private_key = account.from_json(account.to_json())
                print(f"Address: {address} | Private Key: {private_key}")

def thread_worker():
    threads = []
    for _ in range(int(multiprocessing.cpu_count() * multiplicator)):
        th = threading.Thread(target=generate_acc)
        threads.append(th)
        th.start()

    for th in threads:
        th.join()

def main():
    processes = []
    for _ in range(int(multiprocessing.cpu_count() * multiplicator)):
        process = multiprocessing.Process(target=thread_worker)
        processes.append(process)
        process.start()

    for process in processes:
        process.join()

if __name__ == '__main__':
    main()

