        "filename": {
            "type": "string",
            "description": "The name of the file where the text will be saved."
        },
        "text": {
            "type": "string",
            "description": "The text content to be saved in the file."
        }
    }
    output_type = "string"

    def forward(self, filename: str, text: str) -> str:
        if not self.in_workspace(filename):
            raise ValueError(f"Path provided is not in workspace root {self._worspace_root}")

        try:
            abs_path = os.path.abspath(filename)
            dir_name = os.path.dirname(abs_path)
            os.makedirs(dir_name, exist_ok=True)

            with open(filename, 'w') as file:
                file.write(text)
            return f"Text successfully saved to {filename}!"
        except Exception as e:
            return f"Failed to save text to {filename}: {str(e)}"

