"""Main entry point for the MCP server."""

import logging
import os
import sys
from typing import Literal, cast

import click

from .server import mcp


@click.command()
@click.option(
    "--transport",
    default="stdio",
    type=click.Choice(["stdio", "sse"]),
    help="Transport type (stdio or sse)",
)
@click.option("--host", default="0.0.0.0", help="Host to listen on (for sse)")
@click.option("--port", default=3001, type=int, help="Port to listen on (for sse)")
@click.option(
    "-v",
    "--verbose",
    count=True,
    help="Verbosity level, use -v or -vv",
)
def main(
    transport,
    host,
    port,
    verbose,
):
    """Main function to run the MCP server with specified transport type."""
    logging_level = logging.WARN
    if verbose == 1:
        logging_level = logging.INFO
    elif verbose >= 2:
        logging_level = logging.DEBUG

    logging.basicConfig(level=logging_level, stream=sys.stderr)
    logger = logging.getLogger(__name__)
    logger.info(
        "Starting MCP server with transport type: %s, verbosity level: %d",
        transport,
        verbose,
    )

    allowed_levels = {"DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL"}
    env_log_level = cast(
        Literal["DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL"],
        os.environ.get("LOG_LEVEL", "DEBUG"),
    )
    mcp.settings.log_level = (
        env_log_level if env_log_level in allowed_levels else "DEBUG"
    )
    if transport == "sse":
        mcp.settings.port = port
        mcp.settings.host = host
        mcp.run(transport="sse")
    elif transport == "stdio":
        mcp.run(transport="stdio")
    else:
        logger.error("Invalid transport type. Use 'sse' or 'stdio'.")
        sys.exit(1)


if __name__ == "__main__":
    main(transport="stdio", host=None, port=None, verbose=False)

#!/usr/bin/env python3
"""
Minimal MCP test server for debugging Windows issues
"""
import sys
import os
import json

# Immediately log to stderr
print("[MCP Test] Starting minimal test server...", file=sys.stderr, flush=True)
print(f"[MCP Test] Python: {sys.version}", file=sys.stderr, flush=True)
print(f"[MCP Test] Executable: {sys.executable}", file=sys.stderr, flush=True)
print(f"[MCP Test] Current dir: {os.getcwd()}", file=sys.stderr, flush=True)
print(f"[MCP Test] Script dir: {os.path.dirname(os.path.abspath(__file__))}", file=sys.stderr, flush=True)

try:
    # Basic MCP server without dependencies
    def send_message(msg):
        """Send a JSON-RPC message"""
        json_msg = json.dumps(msg)
        sys.stdout.write(f"{json_msg}\n")
        sys.stdout.flush()
        print(f"[MCP Test] Sent: {json_msg}", file=sys.stderr, flush=True)

    # Send initialization response
    print("[MCP Test] Sending initialize response...", file=sys.stderr, flush=True)

    # Wait for initialize request
    while True:
        line = sys.stdin.readline()
        if not line:
            print("[MCP Test] EOF received", file=sys.stderr, flush=True)
            break

        print(f"[MCP Test] Received: {line.strip()}", file=sys.stderr, flush=True)

        try:
            msg = json.loads(line)
            if msg.get("method") == "initialize":
                # Send response
                response = {
                    "jsonrpc": "2.0",
                    "id": msg.get("id"),
                    "result": {
                        "protocolVersion": "0.1.0",
                        "capabilities": {
                            "tools": {
                                "listChanged": False
                            }
                        },
                        "serverInfo": {
                            "name": "minimal-test",
                            "version": "1.0.0"
                        }
                    }
                }
                send_message(response)

                # Send initialized notification
                initialized = {
                    "jsonrpc": "2.0",
                    "method": "notifications/initialized"
                }
                send_message(initialized)

            elif msg.get("method") == "tools/list":
                # Return empty tools list
                response = {
                    "jsonrpc": "2.0",
                    "id": msg.get("id"),
                    "result": {
                        "tools": []
                    }
                }
                send_message(response)

        except json.JSONDecodeError as e:
            print(f"[MCP Test] JSON decode error: {e}", file=sys.stderr, flush=True)
        except Exception as e:
            print(f"[MCP Test] Error: {e}", file=sys.stderr, flush=True)

except Exception as e:
    print(f"[MCP Test] Fatal error: {e}", file=sys.stderr, flush=True)
    import traceback
    traceback.print_exc(file=sys.stderr)
    sys.exit(1)

