def extract_boxed_content(text):
    result = []
    i = 0
    pattern = r'\boxed{'
    len_pattern = len(pattern)

    while i < len(text):
        # 搜索模式 \boxed{
        if text[i:i+len_pattern] == pattern:
            start = i + len_pattern
            brace_level = 1
            content = []
            i = start

            while i < len(text) and brace_level > 0:
                if text[i] == '{':
                    brace_level += 1
                elif text[i] == '}':
                    brace_level -= 1
                if brace_level > 0:
                    content.append(text[i])
                i += 1

            if brace_level == 0:
                result.append(''.join(content))
        else:
            i += 1
    if len(result) == 0:
        return ['No Answer']
    return result
