    class _RUsageInfoV6(ctypes.Structure):
        _fields_ = [("ri_uuid", ctypes.c_uint8 * 16),
                    ("ri_user_time", ctypes.c_uint64),
                    ("ri_system_time", ctypes.c_uint64),
