import os
from azure.core.credentials import AzureKeyCredential
from azure.ai.language.conversations.aio import ConversationAnalysisClient

class CLUResult:
    def __init__(self, intent, score, entities=None):
        self.intent = intent
        self.score = score
        self.entities = entities or {}

async def detect_intent(text):
    endpoint = os.getenv("CLU_ENDPOINT")
    key = os.getenv("CLU_KEY")
    project_name = os.getenv("CLU_PROJECT_NAME", "support-bot-clu")
    deployment_name = os.getenv("CLU_DEPLOYMENT_NAME", "production")
    if not endpoint or not key:
        return CLUResult(intent="unknown", score=0.0)
    client = ConversationAnalysisClient(endpoint, AzureKeyCredential(key))
    async with client:
        result = await client.analyze_conversation(
            task={
                "kind": "Conversation",
                "analysisInput": {"conversationItem": {"participantId": "1", "id": "1", "modality": "text", "language": "en", "text": text}},
                "parameters": {"projectName": project_name, "deploymentName": deployment_name, "verbose": True}
            }
        )
        top_intent = result["result"]["prediction"]["topIntent"]
        score = result["result"]["prediction"]["intents"][top_intent]["confidenceScore"]
        # Extract entities
        entities = {}
        for ent in result["result"]["prediction"].get("entities", []):
            category = ent.get("category")
            val = ent.get("text")
            if category and val:
                entities[category.lower()] = val
        return CLUResult(intent=top_intent, score=score, entities=entities)

