#!/usr/bin/env python3
import socket, threading, json

HOST = '127.0.0.1'
PORT = 5000

def send(sock, msg):
    sock.sendall((json.dumps(msg)+'\n').encode())

def recv(sock):
    buf = b''
    while not buf.endswith(b'\n'):
        part = sock.recv(1024)
        if not part:
            return None
        buf += part
    return json.loads(buf.decode().strip())

def listener(sock):
    while True:
        msg = recv(sock)
        if not msg:
            break
        t = msg.get('type')

        if t == 'question':
            print(f"\nDomanda #{msg['id']}: {msg['question']}")
            for i,o in enumerate(msg['options']):
                print(f"  {i}. {o}")
            ans = input("Risposta (numero): ")
            send(sock, {'type':'answer','id':msg['id'],'choice':int(ans)})

        elif t == 'result':
            status = "CORRETTO" if msg['correct'] else "SBAGLIATO"
            print(f"[{status}] Punteggio: {msg['score']}")

        elif t == 'session_end':
            print("\n-- Fine sessione --")
            for e in msg['ranking']:
                print(f"  {e['user']}: {e['pts']} pt")
            print()

        elif t in ('ok','info','error'):
            print(f"[{t.upper()}] {msg.get('msg')}")

        elif t == 'leaderboard':
            print("\n-- Classifica Globale --")
            for e in msg['entries']:
                print(f"  {e['user']}: {e['score']} pt")
            print()

        else:
            print(msg)

def main():
    sock = socket.socket()
    sock.connect((HOST, PORT))
    threading.Thread(target=listener, args=(sock,), daemon=True).start()
    print("Connesso a LinQuiz!")

    while True:
        cmd = input("Comando (register/login/start/leaderboard/exit): ").strip()
        if cmd == 'register':
            u = input("Username: "); p = input("Password: ")
            send(sock, {'type':'register','user':u,'pass':p})

        elif cmd == 'login':
            u = input("Username: "); p = input("Password: ")
            send(sock, {'type':'login','user':u,'pass':p})

        elif cmd == 'start':
            send(sock, {'type':'start'})

        elif cmd == 'leaderboard':
            send(sock, {'type':'leaderboard'})

        elif cmd == 'exit':
            send(sock, {'type':'exit'})
            break

        else:
            print("Comando non riconosciuto.")

    sock.close()
    print("Disconnesso da LinQuiz.")

if __name__ == '__main__':
    main()

import base64
from openai import OpenAI
from typing import List, Optional
import os

class DoubaoVisionLLM:
    def __init__(
        self, 
        model_name: str,
        api_key: Optional[str] = None,
        base_url: str = "https://ark.cn-beijing.volces.com/api/v3"
    ):
        self.model_name = model_name
        self.client = OpenAI(
            base_url=base_url,
            api_key=api_key or os.getenv("ARK_API_KEY")
        )

    def _get_image_mime_type(self, image_path: str) -> str:
        """Get the MIME type based on the image file extension."""
        ext = image_path.lower().split('.')[-1]
        mime_types = {
            'jpg': 'image/jpeg',
            'jpeg': 'image/jpeg',
            'png': 'image/png'
        }
        return mime_types.get(ext, 'image/jpeg')

    def _image_to_base64(self, image_path: str) -> str:
        with open(image_path, "rb") as image_file:
            return base64.b64encode(image_file.read()).decode('utf-8')

    def generate_response(
        self,
        prompt: str,
        image_paths: List[str],
        system_prompt: str = "你是一个结合文本与图片回答问题的AI助手。"
    ) -> str:
        completion = self.client.chat.completions.create(
            model=self.model_name,
            messages=[
                {"role": "system", "content": system_prompt},
                {"role": "user", 
                 "content": [
                    {"type": "text", "text": prompt},
                    *[
                        {
                            "type": "image_url",
                            "image_url": {
                                "url": image_path if image_path.startswith(("http://", "https://")) else f"data:{self._get_image_mime_type(image_path)};base64,{self._image_to_base64(image_path)}" ,
                            },
                        }
                        for image_path in image_paths
                    ]
                ]},
            ],
        )
        return completion.choices[0].message.content

