def get_vulnerabilities(package_name):
    """
    使用 GitHub Security Advisory (GHSA) GraphQL API 查询漏洞信息。
    """
    if not GITHUB_TOKEN:
        logger.error("错误: 环境变量 GITHUB_TOKEN 未设置。请先设置您的GitHub Personal Access Token。")
        return {"vulns": []}

    # GraphQL 查询语句 (增加了 identifiers 字段以获取CVE)
    query = """
    query GetVulnerabilities($ecosystem: SecurityAdvisoryEcosystem, $packageName: String!) {
      securityVulnerabilities(ecosystem: $ecosystem, package: $packageName, first: 100) {
        edges {
          node {
            advisory {
              ghsaId
              summary
              description
              severity
              references {
                url
              }
              identifiers {
                type
                value
              }
            }
            package {
              name
              ecosystem
            }
            vulnerableVersionRange
            firstPatchedVersion {
              identifier
            }
          }
        }
      }
    }
    """

    variables = {
        "packageName": package_name
    }

    headers = {
        "Authorization": f"bearer {GITHUB_TOKEN}",
        "Content-Type": "application/json"
    }

    logger.info(f"正在查询项目 {package_name} 的漏洞信息...")
    try:
        response = requests.post(GHSA_API_URL, json={'query': query, 'variables': variables}, headers=headers)
        response.raise_for_status()
        data = response.json()

        if 'errors' in data:
            logger.error(f"GitHub API 返回错误: {data['errors']}")
            return {"vulns": []}

        vulnerabilities = data.get('data', {}).get('securityVulnerabilities', {}).get('edges', [])
        logger.info(f"成功获取到 {len(vulnerabilities)} 个漏洞信息")

    except requests.exceptions.RequestException as e:
        logger.error(f"获取漏洞信息失败: {e}")
        return {"vulns": []}

    # 增强和格式化漏洞数据
    enriched_vulns = []
    for edge in vulnerabilities:
        node = edge['node']
        advisory = node['advisory']

        # --- 新增逻辑: 优先使用CVE ID ---
        cve_id = None
        for identifier in advisory.get('identifiers', []):
            if identifier.get('type') == 'CVE':
                cve_id = identifier.get('value')
                break  # 找到CVE后即可停止搜索

        primary_id = cve_id if cve_id else advisory.get('ghsaId')
        ghsa_id = advisory.get('ghsaId')
        # --- 逻辑结束 ---

        # 生成安全建议
        security_advise = "1. 实施严格的输入验证和请求过滤。\n2. 定期更新依赖组件以减少安全风险。"
        if node.get('firstPatchedVersion'):
            fixed_version = node['firstPatchedVersion']['identifier']
            security_advise = f"1. 升级到版本 {fixed_version} 或更高版本以修复此漏洞。\n" + security_advise

        # 提取严重级别
        severity_level = advisory.get('severity', 'UNKNOWN').upper()

        enriched_vuln = {
            "id": primary_id, # 使用主ID (CVE或GHSA) 用于文件名和去重
            "package_name": node['package']['name'],
            "summary": advisory.get('summary', ''),
            "details": advisory.get('description', ''),
            "severity_level": severity_level,
            "version_range": node.get('vulnerableVersionRange', ''),
            "security_advise": security_advise,
            "references": [ref['url'] for ref in advisory.get('references', [])],
            # 为 generate_yaml 函数保留的字段
            "cve": primary_id, # 在YAML中，cve字段将是CVE或GHSA
            "ghsa": ghsa_id,   # 始终保留GHSA ID
            "cvss": f"Severity: {severity_level}"
        }
        enriched_vulns.append(enriched_vuln)

    return {"vulns": enriched_vulns}


