import pandas as pd
import numpy as np


def load_data(filepath):
    df = None
    try:
        df = pd.read_csv(filepath)
        df['date'] = pd.to_datetime(df['date'])
    except:
        pass

    return df


def find_sensors_count(df):
    columns = df.columns

    temp_sensors = 0
    humidity_sensors = 0

    for column in columns:
        if column.startswith('T') and column[1:].isdigit():
            temp_sensors += 1
        elif column.startswith('RH_') and column[3:].isdigit():
            humidity_sensors += 1

    return temp_sensors, humidity_sensors


def check_sensor_sequence(df, errors, prefix):
    if prefix == 'T':
        pattern = prefix
        start_idx = 1
    else:
        pattern = prefix + '_'
        start_idx = 1

    sensor_cols = [col for col in df.columns if col.startswith(pattern)]
    sensor_nums = []

    for col in sensor_cols:
        try:
            if prefix == 'T':
                num = int(col[1:])
            else:
                num = int(col[3:])
            sensor_nums.append(num)
        except ValueError:
            continue

    if not sensor_nums:
        return True

    max_num = max(sensor_nums)
    expected_nums = set(range(start_idx, max_num + 1))
    actual_nums = set(sensor_nums)

    missing_nums = expected_nums - actual_nums
    if missing_nums:
        errors.append(f"Для {prefix} отсутствуют сенсоры: {sorted(missing_nums)}")
        return False
    return True


def validate_data(df):
    try:
        errors = []
        df = df.copy()

        mandatory_columns = ['date', 'Appliances', 'lights', 'T_out', 'RH_out']
        for col in mandatory_columns:
            if col not in df.columns:
                errors.append(f"Обязательный столбец '{col}' отсутствует")

        if 'date' in df.columns:
            try:
                df['date'] = pd.to_datetime(df['date'])
            except Exception as e:
                errors.append(f"Не удалось преобразовать столбец 'date' в datetime: {str(e)}")

        check_sensor_sequence(df, errors, 'T')
        check_sensor_sequence(df, errors, 'RH')

        if errors:
            raise ValueError("Обнаружены ошибки:\n" + "; ".join(errors))

        expected_dtypes = {
            'date': 'datetime64[ns]',
            'Appliances': 'int64',
            'lights': 'int64',
            'T_out': 'float64',
            'RH_out': 'float64'
        }

        type_errors = []

        for col in df.columns:
            if col.startswith('T') and col[1:].isdigit():
                expected_dtypes[col] = 'float64'
            elif col.startswith('RH_') and col[3:].isdigit():
                expected_dtypes[col] = 'float64'

        for col, expected_type in expected_dtypes.items():
            if col not in df.columns:
                continue

            actual_type = str(df[col].dtype)
            if actual_type != expected_type:
                type_errors.append(f"Столбец '{col}': ожидаемый тип {expected_type}, получен {actual_type}")

        if type_errors:
            raise TypeError("Ошибки типов данных:\n" + "; ".join(type_errors))

    except Exception as e:
        return False, e

    return True, None

"""Main changelog generator."""

from collections import defaultdict
from datetime import datetime
from pathlib import Path
from typing import Dict, List, Optional

from ..utils.exceptions import ChangelogError
from .config import Config
from .formatter import ChangelogEntry, ChangelogFormatter
from .git import Commit, GitRepository
from .parser import ConventionalCommitParser, ParsedCommit


class ChangelogGenerator:
    """Main changelog generator class."""

    def __init__(self, repo_path: Path, config: Optional[Config] = None) -> None:
        """Initialize changelog generator."""
        self.repo_path = repo_path
        self.config = config or Config()

        # Initialize components
        self.git_repo = GitRepository(repo_path)
        self.parser = ConventionalCommitParser(
            breaking_change_indicators=self.config.breaking_change_indicators
        )
        self.formatter = ChangelogFormatter(template_path=self.config.template_path)

    def generate(self) -> str:
        """Generate changelog content."""
        try:
            # Get commits from repository
            commits = self.git_repo.get_commits(
                since=self.config.since_tag,
                until=self.config.until_tag,
                include_merges=self.config.include_merges,
            )

            if not commits:
                raise ChangelogError("No commits found in the specified range")

            # Parse commits
            parsed_commits = self._parse_commits(commits)

            if not parsed_commits:
                raise ChangelogError("No valid conventional commits found")

            # Group commits by version/tag
            entries = self._group_commits_by_version(parsed_commits)

            # Format changelog
            return self.formatter.format(entries, self.config.output_style)

        except Exception as e:
            if isinstance(e, ChangelogError):
                raise
            raise ChangelogError(f"Failed to generate changelog: {e}")

    def _parse_commits(
        self, commits: List[Commit]
    ) -> List[tuple[Commit, ParsedCommit]]:
        """Parse commits using conventional commits parser."""
        parsed_commits = []

        for commit in commits:
            # Skip commits that match exclude patterns
            if self._should_exclude_commit(commit):
                continue

            try:
                parsed_commit = self.parser.parse(commit.message)

                # Only include commits of specified types
                if self.config.should_include_commit_type(parsed_commit.type):
                    parsed_commits.append((commit, parsed_commit))

            except Exception:
                # Skip commits that don't follow conventional format
                continue

        return parsed_commits

    def _should_exclude_commit(self, commit: Commit) -> bool:
        """Check if commit should be excluded based on patterns."""
        if not self.config.exclude_patterns:
            return False

        message = commit.message.lower()
        for pattern in self.config.exclude_patterns:
            if pattern.lower() in message:
                return True

        return False

    def _group_commits_by_version(
        self, parsed_commits: List[tuple[Commit, ParsedCommit]]
    ) -> List[ChangelogEntry]:
        """Group commits by version/tag."""
        # Get tags from repository
        tags = self.git_repo.get_tags()

        if not tags:
            # No tags, create single "Unreleased" entry
            return self._create_unreleased_entry(parsed_commits)

        # Sort tags by date (newest first)
        tags.sort(key=lambda t: t.date, reverse=True)

        entries = []
        remaining_commits = parsed_commits.copy()

        # Process each tag
        for i, tag in enumerate(tags):
            # Get commits for this version
            if i == 0:
                # Latest tag - commits from tag to HEAD
                version_commits = [
                    (commit, parsed)
                    for commit, parsed in remaining_commits
                    if commit.date >= tag.date
                ]
            else:
                # Previous tag - commits between this tag and next tag
                next_tag = tags[i - 1]
                version_commits = [
                    (commit, parsed)
                    for commit, parsed in remaining_commits
                    if tag.date <= commit.date < next_tag.date
                ]

            if version_commits:
                entry = self._create_version_entry(tag.name, tag.date, version_commits)
                entries.append(entry)

                # Remove processed commits
                for commit_tuple in version_commits:
                    if commit_tuple in remaining_commits:
                        remaining_commits.remove(commit_tuple)

        # Add unreleased commits if any
        if remaining_commits:
            unreleased_entry = self._create_unrelease

from enum import Enum
from langchain.text_splitter import CharacterTextSplitter, RecursiveCharacterTextSplitter
from langchain_text_splitters import HTMLHeaderTextSplitter, MarkdownHeaderTextSplitter, RecursiveJsonSplitter
from transformers import GPT2TokenizerFast
from langchain_text_splitters import SentenceTransformersTokenTextSplitter

class SplitterAlgorithm(Enum):
    FIXED_LENGTH = 1
    RECURSIVE_CHARACTER = 2
    HTML_HEADER = 3
    MARKDOWN_HEADER = 4
    SENTENCE_TRANSFORMERS = 5
    HUGGINGFACE_TOKENIZER = 6

def read_text(file_path):
    with open(file_path, 'r', encoding='utf-8') as file:
        return file.read()

def split_text(text, algorithm, **kwargs):
    if algorithm == SplitterAlgorithm.FIXED_LENGTH:
        chunk_length = kwargs.get('chunk_length', 200)
        chunks = [text[i:i + chunk_length] for i in range(0, len(text), chunk_length)]
        return chunks

    elif algorithm == SplitterAlgorithm.RECURSIVE_CHARACTER:
        text_splitter = RecursiveCharacterTextSplitter(
            chunk_size=kwargs.get('chunk_size', 200),
            chunk_overlap=kwargs.get('chunk_overlap', 20)
        )
        return text_splitter.create_documents([text])

    elif algorithm == SplitterAlgorithm.HTML_HEADER:
        headers_to_split_on = kwargs.get('headers_to_split_on', [("h1", "Header 1"), ("h2", "Header 2"), ("h3", "Header 3")])
        html_splitter = HTMLHeaderTextSplitter(headers_to_split_on=headers_to_split_on)
        return html_splitter.split_text(text)

    elif algorithm == SplitterAlgorithm.MARKDOWN_HEADER:
        headers_to_split_on = kwargs.get('headers_to_split_on', [("#", "Header 1"), ("##", "Header 2"), ("###", "Header 3")])
        markdown_splitter = MarkdownHeaderTextSplitter(headers_to_split_on=headers_to_split_on)
        return markdown_splitter.split_text(text)

    elif algorithm == SplitterAlgorithm.SENTENCE_TRANSFORMERS:
        splitter = SentenceTransformersTokenTextSplitter(
            model_name=kwargs.get('model_name', "sentence-transformers/all-mpnet-base-v2"),
            chunk_size=kwargs.get('chunk_size', 200),
            chunk_overlap=kwargs.get('chunk_overlap', 20)
        )
        return splitter.split_text(text)

    elif algorithm == SplitterAlgorithm.HUGGINGFACE_TOKENIZER:
        tokenizer = GPT2TokenizerFast.from_pretrained("gpt2")
        text_splitter = CharacterTextSplitter.from_huggingface_tokenizer(
            tokenizer,
            chunk_size=kwargs.get('chunk_size', 100),
            chunk_overlap=kwargs.get('chunk_overlap', 0)
        )
        return text_splitter.split_text(text)

    else:
        raise ValueError("Unsupported algorithm")

